window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"gl6EGofcv2U","speaker":"Abdullatif bin Rashid Al Zayani","role":"Minister for Foreign Affairs","country":"Bahrain","region":"Middle East","url":"https://www.youtube.com/watch?v=gl6EGofcv2U","date":"20260926","title":"🇧🇭 Bahrain - Minister for Foreign Affairs Addresses UN General Debate, 81st Session | #UNGA","seconds":1333,"words":2364,"counts":{"claims":30,"promises":1,"attacks":2},"topics":[{"topic":"Maritime security","share":0.1486,"seconds":198},{"topic":"Iran","share":0.1115,"seconds":149},{"topic":"Strait of Hormuz","share":0.1105,"seconds":147},{"topic":"AI governance","share":0.1091,"seconds":145},{"topic":"Bahrain Strait","share":0.0649,"seconds":87},{"topic":"Palestine","share":0.0588,"seconds":78},{"topic":"Freedom of navigation","share":0.0582,"seconds":78},{"topic":"Sudan","share":0.0559,"seconds":75},{"topic":"Bahrain vision","share":0.0503,"seconds":67},{"topic":"UN implementation","share":0.0484,"seconds":64},{"topic":"Red Sea security","share":0.0471,"seconds":63},{"topic":"Bahraini coexistence","share":0.0465,"seconds":62},{"topic":"UNGA greetings","share":0.0452,"seconds":60},{"topic":"Bahrain waterways","share":0.045,"seconds":60}],"timeline":[[2,67,null],[68,128,"UNGA greetings"],[130,197,"Iran"],[199,280,"Iran"],[281,359,"Strait of Hormuz"],[359,429,"Strait of Hormuz"],[430,490,"Bahrain waterways"],[491,553,"Red Sea security"],[555,641,"Bahrain Strait"],[643,712,"Maritime security"],[714,779,"Maritime security"],[781,844,"Maritime security"],[847,925,"Palestine"],[926,1001,"Sudan"],[1002,1064,"Bahraini coexistence"],[1066,1144,"AI governance"],[1146,1213,"AI governance"],[1214,1291,"Freedom of navigation"],[1293,1358,"UN implementation"],[1359,1426,"Bahrain vision"],[1427,1436,null]],"stances":{"UNGA greetings":"The speaker conveys greetings from the King of Bahrain and expresses appreciation for Bangladesh and the Secretary-General.","Iran":"The speaker states that the Arab Gulf is facing a severe security situation due to unjustified Iranian attacks on civilian infrastructure and facilities.","Strait of Hormuz":"The speaker condemns the targeting of commercial vessels and mining of shipping lanes in the Straits of Hormuz as violations of international law that have global economic consequences, while expressing solidarity with affected nations.","Bahrain waterways":"The speaker rejects any permit or fee regime on international waterways and warns that such actions set a dangerous precedent for global trade.","Red Sea security":"Abdullatif bin Rashid Al Zayani asserts that the right of passage remains valid regardless of alternatives and that threats to specific waterways constitute a threat to all international navigation.","Bahrain Strait":"The speaker asserts that Bahrain, leading the GCC and Jordan, successfully secured international condemnation of attacks on the strait and navigation obstruction through multiple UN resolutions.","Maritime security":"The speaker emphasizes the necessity of holding responsible parties accountable for damages and highlights Bahrain's role in maintaining a rules-based maritime order through hosting combined maritime forces.","Palestine":"The speaker reaffirms support for a geographically contiguous Palestinian state living in peace with Israel and notes Bahrain's role as a founding member of the border of peace initiative.","Sudan":"Calls for an immediate ceasefire, protection of civilians, unhindered humanitarian access, and a political solution preserving Sudan's unity.","Bahraini coexistence":"Abdullatif bin Rashid Al Zayani states that peaceful coexistence is central to Bahraini identity and details the country's initiatives, declarations, and centers established to promote religious freedom and tolerance.","AI governance":"The speaker advocates for an international treaty to govern artificial intelligence development to ensure it contributes to peace rather than conflict.","Freedom of navigation":"The speaker argues that freedom of navigation is a global development necessity and that economic interdependence serves as a shield against coercion.","UN implementation":"Abdullatif bin Rashid Al Zayani asserts that the United Nations requires greater capacity to implement adopted resolutions and recognized rights rather than creating new ones.","Bahrain vision":"The speaker states that Bahrain's future is guided by the King's vision, which prioritizes human dignity, dialogue, and adherence to international law."},"claims":[{"t":174,"quote":"The states of the Gulf Corporation Council and the Hashimite Kingdom of Jordan have been subjected to waves of unjustified Iranian attacks involving ballistic missiles and drones targeting civilian infrastructure, residential areas, ports, airports and energy facilities.","topic":"Iran","kind":"fact"},{"t":238,"quote":"Our countries have been subjected to nearly 7,000 at the hands of Iran involving 1,700 ballistic missiles, 80 cruise missiles, and 5,220 2,000 cargo vessels and tankers with seaf farers on board have also been detained while 72 commercial vessels have been targeted resulting in the deaths of 22 seaf farers.","topic":"Iran","kind":"number"},{"t":297,"quote":"Commercial vessels have been targeted in the Straits of Hormuz. Mines have been laid in an international shipping lane.","topic":"Strait of Hormuz","kind":"fact"},{"t":308,"quote":"on passage have been imposed in contravention of international law.","topic":"Strait of Hormuz","kind":"fact"},{"t":409,"quote":"the right of transit through it is established for the vessels of all states under the UN convention on the law of the sea","topic":"Strait of Hormuz","kind":"fact"},{"t":454,"quote":"Such actions would set an extremely dangerous precedent because what is accepted today in one may be demanded tomorrow in every international waterway upon which global trade depends.","topic":"Bahrain waterways","kind":"fact"},{"t":516,"quote":"Security Council resolution 2817 also referred to Babel Mendab recognizing that a threat to one waterway is a threat to navigation through all waterways.","topic":"Red Sea security","kind":"fact"},{"t":582,"quote":"Bahrain led efforts resulting in the adoption of Security Council resolution 2817 with a historic and unprecedented support of 136 countries.","topic":"Bahrain Strait","kind":"fact"},{"t":595,"quote":"The resolution condemned the attacks against our countries, reaffirming their sovereignty and rejecting any action intended to close the straight or obstruct navigation through it.","topic":"Bahrain Strait","kind":"fact"},{"t":658,"quote":"On the 17th of this month, the kingdom convened an a formula meeting of the security council dedicated to freedom of In this session, we heard from 53 affected states, the maritime transport sector and relevant international bodies.","topic":"Maritime security","kind":"fact"},{"t":696,"quote":"The kingdom contributes to the protection of a rules-based maritime order across an area exceeding 3 million square miles through its hosting in Manama of the headquarters of the combined maritime forces.","topic":"Maritime security","kind":"self_credit"},{"t":714,"quote":"This comprises 47 nations.","topic":"Maritime security","kind":"number"},{"t":727,"quote":"The kingdom is proud to in the alliance as a founding member","topic":"Maritime security","kind":"self_credit"},{"t":804,"quote":"His Royal Highness, Prince Salman bin Muhammad al- Khalifa, Crown Prince and Prime Minister, said from this very podium two years ago that the systems established to safeguard the international order were under severe strain.","topic":"Maritime security","kind":"fact"},{"t":826,"quote":"He noted that this organization must evolve to confront the growing threats.","topic":"Maritime security","kind":"fact"},{"t":887,"quote":"The kingdom has also joined the border of peace as a founding member pursuant to security council resolution 2803.","topic":"Palestine","kind":"fact"},{"t":926,"quote":"In Sudan, we call for an immediate ceasefire, the protection of civilians, unhindered humanitarian access, and a political solution that preserves Sudan's unity and in the state institutions.","topic":"Sudan","kind":"fact"},{"t":944,"quote":"Turning to Yemen, we renew our support for a political solution under United Nations opices led by the legitimate government.","topic":"Sudan","kind":"fact"},{"t":1013,"quote":"we have introduced the initiative adopted by the general assembly designating the 28th of January as the international day of peaceful coexistence.","topic":"Bahraini coexistence","kind":"fact"},{"t":1022,"quote":"His majesty the king also issued the kingdom of Bahrain's declaration on religious freedom and freedom of belief.","topic":"Bahraini coexistence","kind":"fact"},{"t":1031,"quote":"The King Hammed Global Center for Coexistence and tolerance was later established and the King Hammed Award for Coexistence and tolerance was","topic":"Bahraini coexistence","kind":"fact"},{"t":1088,"quote":"From this podium two years ago, his royal highness, the crown prince and prime minister called for the adoption of an international treaty governing the development of artificial intelligence.","topic":"AI governance","kind":"fact"},{"t":1109,"quote":"Since then, the General Assembly has taken positive steps.","topic":"AI governance","kind":"fact"},{"t":1146,"quote":"A safeguard adopted by a single state is not a safeguard just as a rule that applies in a single state is not a rule.","topic":"AI governance","kind":"fact"},{"t":1203,"quote":"There can be no prosperity without security and no sustainable security without interconnected economies and societies in peace.","topic":"AI governance","kind":"fact"},{"t":1226,"quote":"A lesson that Europe learned when it built its peace not through treaties alone but on interests so intertwined that separating them became costlier than preserving","topic":"Freedom of navigation","kind":"fact"},{"t":1254,"quote":"It is an artery of development through which the food, medicine and energy of entire nations flaw","topic":"Freedom of navigation","kind":"fact"},{"t":1347,"quote":"A resolution adopted but not implemented has no value. and a right that is recognized but not protected has no value or meaning.","topic":"UN implementation","kind":"fact"},{"t":1361,"quote":"the kingdom of Bahrain continues to be guided by his majesty's vision for as his majesty sees it is not declared but built","topic":"Bahrain vision","kind":"fact"},{"t":1376,"quote":"It can rest only on the respect for human beings dignities and beliefs","topic":"Bahrain vision","kind":"fact"}],"promises":[{"t":1390,"quote":"The kingdom will remain faithful to its international commitments and covenants, committed to international law, to freedom of navigation, and to a just, comprehensive, and lasting peace","topic":"Bahrain vision","kind":"promise"}],"attacks":[{"t":199,"quote":"This came in flagrant violation of international law and the charter of the United Nations.","topic":"Iran","target":"Iran"},{"t":206,"quote":"These are indiscriminate attacks without justification under any law.","topic":"Iran","target":"Houthis"}],"greece":[],"said":[],"pickup":[],"transcript":[{"t":2,"topic":null,"text":"And now I give the floor to his excellency Abdulatif bin Rashid al- Minister of foreign for foreign affairs of Bahrain. In the name of God, the most gracious, the most merciful. Your Excellency Dr. Khaled Rahman, President of the United Nations General Assembly. Your Excellency Mr. Antonia Gutes, Secretary General of the United Nations. Ladies and gentlemen, peace and blessings of God be upon you. Allow me to congratulate you, excellency, on your election as president of the 81st session of the general assembly."},{"t":68,"topic":"UNGA greetings","text":"I wish you every success in conducting the work of this session. We would like to express the Kingdom of Bahrain's appreciation to your brotherly country, the People's Republic of Bangladesh, as well as the Secretary General, for his tireless efforts in the service of international peace and security and the sustainable development goals. It is my honor to convey to this distinguished gathering the greetings of his majesty Kinghammed bin Isa al- Khalifa, King of the Kingdom of Bahrain and of his Royal Highness Prince Salman bin al- Khalifa, Crown Prince and Prime and their best wishes for the success of the session. Mr. President, you have chosen for this session a theme that speaks directly to the challenges before us."},{"t":130,"topic":"Iran","text":"Restoring trust, managing transformation, and a united Nations that delivers for Trust is not restored through statements or by repeating appeals. Instead, it is restored by upholding the law and translating the decisions of this organization into effective protection for people's lives, rights, and We meet at a time when the Arab Gulf is facing a security situation of a severity not witnessed in decades. The states of the Gulf Corporation Council and the Hashimite Kingdom of Jordan have been subjected to waves of unjustified Iranian attacks involving ballistic missiles and drones targeting civilian infrastructure, residential areas, ports, airports and energy facilities."},{"t":199,"topic":"Iran","text":"This came in flagrant violation of international law and the charter of the United Nations. These are indiscriminate attacks without justification under any law. My country also condemns the attacks carried out by the Iranbacked terrorist Houthi militia against civilian objects and Islamic holy sites in the brotherly kingdom of Saudi Arabia. We also condemn their threats to freedom of navigation in the Babel Mandubab and the Red Sea. Allow me to put the facts before you in figures. Our countries have been subjected to nearly 7,000 at the hands of Iran involving 1,700 ballistic missiles, 80 cruise missiles, and 5,220 2,000 cargo vessels and tankers with seaf farers on board have also been detained while 72 commercial vessels have been targeted resulting in the deaths of 22 seaf farers."},{"t":281,"topic":"Strait of Hormuz","text":"These are not merely numbers. Behind every figure is a ship, a port, a market, and families waiting for those that provide for them to return home. Commercial vessels have been targeted in the Straits of Hormuz. Mines have been laid in an international shipping lane. on passage have been imposed in contravention of international law. The consequences of all the above extend far beyond the Arabian Gulf. It affects energy and food prices, shipping and insurance costs as well as supply chains across the world. As the kingdom renews its full solidarity with the brotherly countries subjected to these attacks, it commends the professionalism of the Bahrain defense force and the air defense forces of brotherly countries [snorts] and their readiness in confronting these attacks."},{"t":359,"topic":"Strait of Hormuz","text":"We reaffirm the right of all states to take all lawful measures to defend their sovereignty and territorial integrity pursuant to article 51 of the UN charter and the joint defense agreement of the GCC states. All the same, we continue to exercise the utmost restraint seeking to ensure that security and peace prevail for the benefit of the people of the region. Mr. President, the position of the Kingdom of Bahrain is grounded in international law, the rights of people's the Strait of Harris is an international straight and the right of transit through it is established for the vessels of all states under the UN convention on the law of the sea. That right may not be suspended or obstructed, nor may it be subjected to conditions imposed unilaterally by any state."},{"t":430,"topic":"Bahrain waterways","text":"Accordingly, the kingdom categorically rejects any permit or fee regime imposed on the passage. It rejects the use of international waterways as instruments of pressure or economic co urgent or any attempt at the seizure of vessels. Such actions would set an extremely dangerous precedent because what is accepted today in one may be demanded tomorrow in every international waterway upon which global trade depends. Alternative routes cannot be treated as a solution to conduct that that violates international law. Mitigation measures are an emergency response."},{"t":491,"topic":"Red Sea security","text":"They should not be used as a pretext to claim that the state is no longer necessary or to accept a new status quo. The right of passage does not cease to exist because alternatives are available. nor does a violation cease uh just because the those affected have found ways to reduce the loss. This threat is not confined to the straits of harms. Security Council resolution 2817 also referred to Babel Mendab recognizing that a threat to one waterway is a threat to navigation through all waterways. The security of navigation in the Red Sea, the Gulf of Aiden and the Babel is part of the same system. We are now a regional interest, but a rule that applies to every international waterway."},{"t":555,"topic":"Bahrain Strait","text":"And if it does apply to one to our strait alone, it wouldn't have been a The Kingdom of Bahin has not only stated its position in principle on behalf of the Gulf Cooperation Council states and the Hashimite Kingdom of Jordan and by virtue of its current presidency of the GCC and its non-permanent membership of the security council. Bahrain led efforts resulting in the adoption of Security Council resolution 2817 with a historic and unprecedented support of 136 countries. The resolution condemned the attacks against our countries, reaffirming their sovereignty and rejecting any action intended to close the straight or obstruct navigation through it. The kingdom also introduced a draft resolution under chapter 7 of the charter to protect commercial The resolution adopted by the council of the international maritime organization on the 19th of March together with the human rights council resolution 61 both have further demonstrated that the rejection of such conduct extends beyond the security council."},{"t":643,"topic":"Maritime security","text":"We stress the need for the full implementation of these resolutions to ensure that those responsible are held accountable and there are compensation for the damage caused. On the 17th of this month, the kingdom convened an a formula meeting of the security council dedicated to freedom of In this session, we heard from 53 affected states, the maritime transport sector and relevant international bodies. And we heard a conclusion expressed by all delegations that is freedom of passage through international straits is a prerequisite for global economic The kingdom contributes to the protection of a rules-based maritime order across an area exceeding 3 million square miles through its hosting in Manama of the headquarters of the combined maritime forces."},{"t":714,"topic":"Maritime security","text":"This comprises 47 nations. We welcome the establishment of the multinational maritime defense alliance led by the brotherly kingdom of Saudi Arabia. The kingdom is proud to in the alliance as a founding member and supportive efforts to safeguard international trade routes and global energy supplies in accordance with international law. As efforts continue in the security council, this general assembly has an equally important role to play as the forum in which all states stand equal. From this podium, we call upon member states to support a firm collective position which upholds freedom of navigation and the right of transit passage in accordance with international law."},{"t":781,"topic":"Maritime security","text":"It should also affirm that the security of maritime passages is a collective responsibility that cannot be subjected to bilateral arrangements. This is what restoring trust means in This is not a call dictated by the present crisis. His Royal Highness, Prince Salman bin Muhammad al- Khalifa, Crown Prince and Prime Minister, said from this very podium two years ago that the systems established to safeguard the international order were under severe strain. He noted that this organization must evolve to confront the growing threats. He called for comprehensive reform encompassing all decision-making bodies including the security council."},{"t":847,"topic":"Palestine","text":"What has happened since then has not altered that conviction. Instead, it has reinforced it. Mr. President, the test of the United Nations credibility is not only confined to our waters. The Palestinian calls remains at the heart of our concerns. The kingdom reaffirms its steadfast position in support of the establishment of an and geographically contiguous state of Palestine, living side by side with the state of Israel in peace and security. The kingdom has also joined the border of peace as a founding member pursuant to security council resolution 2803. This reaffirms our unwavering support for the rights of the brotherly Palestinian people. The kingdom also reaffirms its support for the unity, sovereignty, and territorial integrity of the Syrian Arab Republic, as well as for efforts to lift sanctions in a manner that enables the brotherly Syrian people to rebuild their country."},{"t":926,"topic":"Sudan","text":"In Sudan, we call for an immediate ceasefire, the protection of civilians, unhindered humanitarian access, and a political solution that preserves Sudan's unity and in the state institutions. Turning to Yemen, we renew our support for a political solution under United Nations opices led by the legitimate government. We appreciate the efforts of the Kingdom of Saudi Arabia in this vein. Our position on other conflicts including the conflict in Ukraine is guided by the same principles regardless of the parties involved. That is adherence to the charter, respect for sovereignty and territorial integrity and the peaceful settlement of disputes. Mr. for president. The kingdom of where mosques, churches, and temples have stood side by side for generations, believes that tolerance and coexistence are not simply policies to be adopted."},{"t":1002,"topic":"Bahraini coexistence","text":"Instead, they are the identity of the Bahraini society and the foundation of our national unity. we have introduced the initiative adopted by the general assembly designating the 28th of January as the international day of peaceful coexistence. His majesty the king also issued the kingdom of Bahrain's declaration on religious freedom and freedom of belief. The King Hammed Global Center for Coexistence and tolerance was later established and the King Hammed Award for Coexistence and tolerance was The same approach underpins our development journey. The kingdom continues to advance its economic vision 2030, pursue its commitment to achieving the sustainable development goals and strengthen the status and advancement of Bahraini women."},{"t":1066,"topic":"AI governance","text":"The kingdom embraces the women peace and security agenda and the youth peace and security agenda. both our priorities during our membership in the security council. No discussion of development today is complete without addressing the technology that is reshaping that development. From this podium two years ago, his royal highness, the crown prince and prime minister called for the adoption of an international treaty governing the development of artificial intelligence. It would ensure that this technology contributes to peace rather than exacerbating conflict. Since then, the General Assembly has taken positive steps. However, dialogue can bring positions closer, but it is not a step that creates obligations. The aim is not to hold the technology that no one has the power to hold but to ensure that its growth is surrounded by Uh just as the international community surrounded nuclear energy with safeguards that preserved its benefits without preventing it, this technology knows no borders."},{"t":1146,"topic":"AI governance","text":"A safeguard adopted by a single state is not a safeguard just as a rule that applies in a single state is not a rule. Therefore, we renew our call for a binding international framework to ensure that this technology becomes a driver of innovation rather than division. And this in our view is what it means to manage the transformation that you chose as a theme of this session. Mr. President, all these issues, however far apart they may seem, are bound by one fundamental truth. Security and prosperity are not two parallel objectives. Instead, they are one single objective pursued along two paths. There can be no prosperity without security and no sustainable security without interconnected economies and societies in peace."},{"t":1214,"topic":"Freedom of navigation","text":"This is not a Gulf perspective dictated by our geography. Instead, it's a lesson that humanity has learned from its wars. A lesson that Europe learned when it built its peace not through treaties alone but on interests so intertwined that separating them became costlier than preserving It is in this light that we view freedom of navigation. A waterway is not mereily a security issue of concern for coastal states. It is an artery of development through which the food, medicine and energy of entire nations flaw. When a single waterway is disrupted, the cost is felt by a family in a country that does not have a An economy that is difficult to disrupt is difficult to coersse and interdependence once firmly established becomes a shield against coercion."},{"t":1293,"topic":"UN implementation","text":"This approach is not a position shaped by the current circumstances. It is what his majesty King Huh bin isa al- Khalifa king of the kingdom of Bahrain has consistently advocated for out of his majesty's conviction that the security and prosperity of this region are two faces of a single truth and that a just peace and lasting stability are the path towards a dignified life for all the peoples of the region, whatever their faiths or cultures. Thus, we reaffirm that what the United Nations needs today is not more but greater capacity to implement them. A resolution adopted but not implemented has no value. and a right that is recognized but not protected has no value or meaning."},{"t":1359,"topic":"Bahrain vision","text":"I conclude by stating that the kingdom of Bahrain continues to be guided by his majesty's vision for as his majesty sees it is not declared but built. It can rest only on the respect for human beings dignities and beliefs. It should be built on dialogue, not concession or strength. The kingdom will remain faithful to its international commitments and covenants, committed to international law, to freedom of navigation, and to a just, comprehensive, and lasting peace. True to his majesty's approach, and to the conviction that the security of our region and the prosperity of its peoples are a shared responsibility that can only be safeguarded through our collective effort. We pray to Almighty God to grant this session every success and to bestow upon our peoples and all humanity security, peace, development and prosperity."},{"t":1427,"topic":null,"text":"Thank you and peace be upon you. &gt;&gt; Thank you. I thank the Minister for Foreign Affairs of Bakra."}],"compare":[{"topic":"Maritime Security","share":0.1556,"mean":0.0039,"rank":2,"others":9},{"topic":"Iran","share":0.1168,"mean":0.0132,"rank":7,"others":25},{"topic":"Strait of Hormuz","share":0.1157,"mean":0.0025,"rank":2,"others":5},{"topic":"Artificial Intelligence","share":0.1143,"mean":0.0501,"rank":30,"others":83},{"topic":"Israel–Palestine","share":0.0615,"mean":0.0524,"rank":60,"others":76},{"topic":"Maritime Law","share":0.0609,"mean":0.0015,"rank":3,"others":4},{"topic":"Sudan","share":0.0586,"mean":0.007,"rank":9,"others":15},{"topic":"UN & its reform","share":0.0507,"mean":0.2056,"rank":167,"others":170}]};
